corporate_design.toad_component_blueprint:
canvas {
  size: 960px 560px;
  fill: #18181B;
  font-family: "JetBrains Mono, monospace";
}

>zincDark = #18181B;
>engineOrange = #F97316;
>deployGreen = #10B981;
>zincCard = #27272A;
>textWhite = #FAFAFA;

rect #pipelineCard {
  at: center of canvas;
  size: 880px 460px;
  fill: >zincCard;
  stroke: #3F3F46;
  stroke-width: 1px;
  radius: 8px;
}

text #repoTitle {
  at: top left of #pipelineCard offset 32px 28px;
  content: "STREAMFLOW // PIPELINE #4298 • MAIN BRANCH";
  font-size: 15px;
  font-weight: 700;
  color: >textWhite;
}

rect #buildStage {
  at: below #repoTitle offset 24px;
  size: 816px 64px;
  fill: #18181B;
  radius: 6px;
}

text #stageText1 {
  at: left center of #buildStage offset 20px 0px;
  content: "✔ 01_BUILD_CONTAINER";
  font-size: 13px;
  font-weight: 700;
  color: >deployGreen;
}

text #stageTime1 {
  at: right center of #buildStage offset -20px 0px;
  content: "42s • PASSED";
  font-size: 12px;
  color: >deployGreen;
}

rect #deployStage {
  at: below #buildStage offset 12px;
  size: 816px 64px;
  fill: #18181B;
  radius: 6px;
}

text #stageText2 {
  at: left center of #deployStage offset 20px 0px;
  content: "⚙ 02_KUBERNETES_ROLLOUT";
  font-size: 13px;
  font-weight: 700;
  color: >engineOrange;
}

text #stageTime2 {
  at: right center of #deployStage offset -20px 0px;
  content: "IN PROGRESS...";
  font-size: 12px;
  color: >engineOrange;
}
